CREATE OR REPLACE FUNCTION public.log_blog_event(p_post_id uuid, p_event_type text, p_session_id text DEFAULT NULL::text, p_referrer text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO blog_events(post_id, event_type, session_id, referrer, country, user_id)
  VALUES (p_post_id, p_event_type, p_session_id, p_referrer, p_country, p_user_id);

  -- Atomically bump the denormalized view_count on the post for fast reads
  IF p_event_type = 'view' THEN
    UPDATE blog_posts SET view_count = view_count + 1 WHERE id = p_post_id;
  END IF;
END;
