CREATE OR REPLACE FUNCTION public.match_help_articles(query_embedding vector, match_count integer DEFAULT 5, role_filter text DEFAULT NULL::text, app_filter text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, title text, content text, role text, similarity double precision)
 LANGUAGE sql
 STABLE
AS $function$
  SELECT
    id,
    title,
    content,
    role,
    1 - (embedding <=> query_embedding) AS similarity
  FROM public.help_articles
  WHERE
    embedding IS NOT NULL
    AND (role_filter IS NULL OR role IN (role_filter, 'all'))
    AND (app_filter IS NULL OR app = app_filter)
  ORDER BY embedding <=> query_embedding
  LIMIT match_count;
$function$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.match_union_chunks(query_embedding vector, match_count integer DEFAULT 5, union_filter text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, document_id uuid, chunk_text text, chunk_index integer, doc_name text, union_local text, similarity double precision)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    c.id,
    c.document_id,
    c.chunk_text,
    c.chunk_index,
    d.name AS doc_name,
    d.union_local,
    1 - (c.embedding <=> query_embedding) AS similarity
  FROM union_document_chunks c
  JOIN union_documents d ON d.id = c.document_id
  WHERE d.status = 'ready'
    AND c.embedding IS NOT NULL
    AND (d.user_id = p_user_id OR d.is_shared = true)
    AND (union_filter IS NULL OR d.union_local = union_filter)
  ORDER BY c.embedding <=> query_embedding
  LIMIT match_count;
END;
$function$;
