CREATE VIEW "expected_payments" WITH (security_invoker=true) AS
SELECT j.user_id,
    'job'::text AS source_type,
    j.id AS source_id,
    j.est_pay_date AS expected_date,
    j.client_name AS label,
    j.job_number AS reference_number,
    COALESCE(( SELECT sum(COALESCE(te.st_hours, te.total_hours, 0::numeric) * COALESCE(j.pay_rate, 0::numeric) + COALESCE(te.ot_hours, 0::numeric) * COALESCE(j.ot_rate, j.pay_rate * 1.5, 0::numeric) + COALESCE(te.dt_hours, 0::numeric) * COALESCE(j.dt_rate, j.pay_rate * 2::numeric, 0::numeric)) AS sum
           FROM job_time_entries te
          WHERE te.job_id = j.id),
        CASE
            WHEN j.rate_type = 'daily'::text AND j.start_date IS NOT NULL AND j.end_date IS NOT NULL THEN j.pay_rate * (j.end_date - j.start_date + 1)::numeric
            WHEN j.rate_type = 'flat'::text THEN j.pay_rate
            ELSE 0::numeric
        END) AS expected_amount,
    j.status,
    j.start_date,
    j.end_date,
    j.brand_id,
    j.created_at
   FROM contractor_jobs j
  WHERE j.est_pay_date IS NOT NULL AND (j.status = ANY (ARRAY['completed'::text, 'invoiced'::text]))
UNION ALL
 SELECT i.user_id,
    'invoice'::text AS source_type,
    i.id AS source_id,
    i.due_date AS expected_date,
    i.contact_name AS label,
    i.invoice_number AS reference_number,
    i.total - i.amount_paid AS expected_amount,
    i.status,
    i.invoice_date AS start_date,
    NULL::date AS end_date,
    i.brand_id,
    i.created_at
   FROM invoices i
  WHERE i.direction = 'receivable'::text AND i.due_date IS NOT NULL AND (i.status = ANY (ARRAY['sent'::text, 'overdue'::text]));
--> statement-breakpoint
CREATE VIEW "public_profiles" WITH (security_barrier=true) AS
SELECT id,
    username,
    display_name,
    bio,
    avatar_url,
    created_at,
    updated_at
   FROM profiles p;
